"use client";

/**
 * Tool calls: one agent turn. Tool-call chips arrive one after another, each
 * spinning until it resolves to a check, then the short answer writes itself
 * word by word. The "it does the work" beat of an AI product film.
 *
 * Written by Better Design. Painted from the theme prop.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { loadFont as loadMono } from "@remotion/google-fonts/JetBrainsMono";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { easings, pickFont, type SoundCue, SoundTrack, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });
const { fontFamily: MONO } = loadMono("normal", { weights: ["500", "600"], subsets: ["latin"] });

const FIRST_AT = 14;
/** Frames between two chips arriving. */
const STEP = 22;
/** Frames a chip spins before it resolves. */
const RUN = 18;
const ENTER = 12;
/** Frames per word of the answer. */
const WORD = 2.5;
const DEFAULT_TOOLS = ["search_docs: billing retries", "read_file: src/billing/retry.ts", "edit_file: src/billing/retry.ts", "run_tests: billing"];

/** The frame the answer starts writing, after the last tool resolves. */
const answerFrame = (toolCount: number): number => FIRST_AT + (toolCount - 1) * STEP + RUN + 10;

/**
 * The sound of a ToolCalls turn: a pop as each chip arrives, alternating
 * takes and stepping down, a soft pop as each one resolves, and a whoosh as
 * the answer writes itself.
 */
export function toolCallsCues(toolCount: number = DEFAULT_TOOLS.length): SoundCue[] {
  const cues: SoundCue[] = [];
  for (let i = 0; i < toolCount; i++) {
    const at = FIRST_AT + i * STEP;
    cues.push({ sfx: i % 2 === 0 ? "pop" : "pop-soft", at: at + 1, gain: -1.5 * i });
    cues.push({ sfx: "pop-soft", at: at + RUN + 4, gain: -8 });
  }
  cues.push({ sfx: "whoosh", at: answerFrame(toolCount) + 6, gain: -6 });
  return cues;
}

export interface ToolCallsProps {
  /** Each entry reads "tool-name: argument". Four to five fit. */
  tools?: string[];
  /** The short reply the agent writes once the tools finish. */
  answer?: string;
  /** Label above the turn. */
  agentName?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
  /** Play the shot's own sound cues. Leave off inside a film that plays every scene's cues in one SoundTrack. */
  sound?: boolean;
}

const split = (entry: string): [string, string] => {
  const at = entry.indexOf(":");
  return at < 0 ? [entry.trim(), ""] : [entry.slice(0, at).trim(), entry.slice(at + 1).trim()];
};

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/** An agent turn: tool calls resolve in sequence, then the answer writes itself. */
export function ToolCalls({
  tools = DEFAULT_TOOLS,
  answer = "Fixed the retry logic in billing and the test suite passes. The change is ready for your review.",
  agentName = "Agent",
  theme: themeOverride,
  font,
  sound = false,
}: ToolCallsProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  const answerAt = answerFrame(tools.length);
  const words = answer.split(/\s+/).filter(Boolean);
  const headT = easings.out(interpolate(frame, [0, 14], [0, 1], clamp));
  const allDone = frame >= answerAt - 10;

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, alignItems: "center", justifyContent: "center" }}>
      {sound ? <SoundTrack cues={toolCallsCues(tools.length)} music={false} /> : null}
      <div style={{ width: 1180, display: "flex", flexDirection: "column", gap: 40 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 18, opacity: headT, transform: `translateY(${(1 - headT) * 14}px)` }}>
          <div style={{ width: 56, height: 56, borderRadius: theme.radius * 1.4, background: theme.primary, display: "flex", alignItems: "center", justifyContent: "center" }}>
            <svg width={30} height={30} viewBox="0 0 24 24">
              <path d="M12 2 L14.2 9.8 L22 12 L14.2 14.2 L12 22 L9.8 14.2 L2 12 L9.8 9.8 Z" fill={theme.primaryForeground} />
            </svg>
          </div>
          <div style={{ fontSize: 34, fontWeight: 600, color: theme.foreground }}>{agentName}</div>
          <div style={{ fontSize: 28, fontWeight: 500, color: theme.mutedForeground }}>
            {allDone ? `Used ${tools.length} tools` : "Working"}
          </div>
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          {tools.map((entry, i) => {
            const [name, arg] = split(entry);
            const at = FIRST_AT + i * STEP;
            const t = easings.out(interpolate(frame, [at, at + ENTER], [0, 1], clamp));
            const done = easings.out(interpolate(frame, [at + RUN, at + RUN + 10], [0, 1], clamp));
            const angle = (frame - at) * 14;
            return (
              <div
                key={i}
                style={{
                  display: "flex", alignItems: "center", gap: 22, padding: "20px 28px", borderRadius: theme.radius * 1.6,
                  background: theme.card, border: `1px solid ${theme.border}`,
                  opacity: t, transform: `translateY(${(1 - t) * 26}px)`,
                }}
              >
                <div style={{ width: 48, height: 48, borderRadius: theme.radius, background: theme.muted, color: theme.mutedForeground, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: MONO, fontSize: 22, fontWeight: 600 }}>
                  {"</>"}
                </div>
                <div style={{ fontFamily: MONO, fontSize: 30, fontWeight: 600, color: theme.foreground }}>{name}</div>
                <div style={{ flex: 1, minWidth: 0, fontFamily: MONO, fontSize: 28, fontWeight: 500, color: theme.mutedForeground, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{arg}</div>
                <div style={{ position: "relative", width: 44, height: 44 }}>
                  <svg width={44} height={44} viewBox="0 0 44 44" style={{ position: "absolute", inset: 0, opacity: 1 - done, transform: `rotate(${angle}deg)` }}>
                    <circle cx={22} cy={22} r={17} fill="none" stroke={withAlpha(theme.mutedForeground, 0.2)} strokeWidth={4} />
                    <circle cx={22} cy={22} r={17} fill="none" stroke={theme.primary} strokeWidth={4} strokeLinecap="round" strokeDasharray="30 107" />
                  </svg>
                  <svg width={44} height={44} viewBox="0 0 44 44" style={{ position: "absolute", inset: 0, opacity: done, transform: `scale(${0.7 + 0.3 * done})` }}>
                    <circle cx={22} cy={22} r={20} fill={theme.primary} />
                    <path d="M13 22.5 L19.5 29 L31 16" fill="none" stroke={theme.primaryForeground} strokeWidth={4} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={30} strokeDashoffset={30 * (1 - done)} />
                  </svg>
                </div>
              </div>
            );
          })}
        </div>

        <div style={{ minHeight: 130, fontSize: 44, fontWeight: 500, lineHeight: 1.35, letterSpacing: "-0.01em", color: theme.foreground }}>
          {words.map((word, i) => {
            const t = easings.out(interpolate(frame, [answerAt + i * WORD, answerAt + i * WORD + 8], [0, 1], clamp));
            return (
              <span key={i} style={{ display: "inline-block", marginRight: "0.28em", opacity: t, transform: `translateY(${(1 - t) * 10}px)`, filter: `blur(${(1 - t) * 4}px)` }}>
                {word}
              </span>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
}
